<?php
require __DIR__.'/server/bootstrap.php';require __DIR__.'/server/commerce.php';require __DIR__.'/server/catalog.php';require __DIR__.'/server/product-management.php';$admin=require_admin();$products=catalog(true);$id=is_string($_GET['id']??null)?$_GET['id']:'';$new=$id==='';$error='';
if(!$new&&!isset($products[$id])){http_response_code(404);exit('Produk tidak ditemukan.');}
$product=$new?['name'=>'','category'=>'Legalitas','label'=>'','description'=>'','price'=>null,'old_price'=>null,'includes'=>[],'bonuses'=>[],'published'=>false]:$products[$id];
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_admin_post();try{
  $data=validate_product($_POST);$published=($_POST['published']??'')==='1';$photo=null;$mime=null;$upload=$_FILES['photo']??null;
  if($upload&&($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if($upload['error']!==UPLOAD_ERR_OK||!is_uploaded_file($upload['tmp_name']))throw new RuntimeException('Unggah foto gagal. Coba kembali dengan foto maksimal 2 MB.');$mime=validate_product_photo($upload['tmp_name'],(int)$upload['size']);$photo=file_get_contents($upload['tmp_name']);}
  $remove=($_POST['remove_photo']??'')==='1';$saveId=$new?'produk-'.bin2hex(random_bytes(10)):$id;$p=db();$p->beginTransaction();
  $q=$p->prepare('INSERT INTO dwa_products(product_id,data_json,published) VALUES (?,?,?) ON DUPLICATE KEY UPDATE data_json=VALUES(data_json),published=VALUES(published)');$q->execute([$saveId,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$published?1:0]);
  $q=$p->prepare('INSERT INTO dwa_prices(product_id,price,old_price) VALUES (?,?,?) ON DUPLICATE KEY UPDATE price=VALUES(price),old_price=VALUES(old_price)');$q->execute([$saveId,$data['price'],$data['old_price']]);
  if($photo!==null||$remove){$q=$p->prepare('UPDATE dwa_products SET photo=?,photo_mime=? WHERE product_id=?');$q->execute([$photo,$mime,$saveId]);}
  audit_admin($admin['id'],$new?'create-product':'edit-product',$saveId);$p->commit();header('Location: admin-products.php?id='.rawurlencode($saveId).'&saved=1');exit;
 }catch(Throwable $ex){if(isset($p)&&$p->inTransaction())$p->rollBack();$error=$ex instanceof RuntimeException&&!$ex instanceof PDOException?$ex->getMessage():'Produk gagal disimpan. Silakan coba kembali.';if(isset($data))$product=array_replace($product,$data,['published'=>$published]);}
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Kelola Produk — DWA</title><link rel="stylesheet" href="shop.css"><link rel="stylesheet" href="admin.css"></head><body><header class="shop-header"><a class="brand" href="kelola-dwa.php">DWA<span>ADMINISTRATION</span></a><nav><a href="kelola-dwa.php">Dashboard admin</a><a href="admin-products.php">+ Produk baru</a></nav></header><main class="shop-main"><span class="eyebrow">KATALOG & PRODUK</span><h1><?=$new?'Tambah produk.':'Edit produk.'?></h1><?php if($error): ?><p class="notice" role="alert"><?=e($error)?></p><?php endif ?><?php if(isset($_GET['saved'])): ?><p class="notice" role="status">Produk berhasil disimpan.</p><?php endif ?><div class="product-admin-layout"><section class="admin-panel"><form method="post" enctype="multipart/form-data"><?php csrf_form();?><input type="hidden" name="MAX_FILE_SIZE" value="2097152"><div class="form-grid"><label>Nama produk<input name="name" maxlength="120" required value="<?=e($product['name'])?>"></label><label>Kategori<select name="category"><?php foreach(['Legalitas','UMKM','Digital'] as $category): ?><option <?=$product['category']===$category?'selected':''?>><?=e($category)?></option><?php endforeach ?></select></label><label class="wide">Subjudul singkat<input name="label" maxlength="180" required value="<?=e($product['label'])?>"></label><label class="wide">Deskripsi produk<textarea name="description" rows="6" maxlength="10000" required><?=e($product['description'])?></textarea></label><label>Harga jual (Rp)<input name="price" type="number" min="0" max="1000000000" value="<?=$product['price']??''?>"><small>Kosongkan untuk meminta penawaran.</small></label><label>Harga normal / coret<input name="old_price" type="number" min="0" max="1000000000" value="<?=$product['old_price']??''?>"></label><label class="wide">Yang didapat (satu item per baris)<textarea name="includes" rows="5" maxlength="6000"><?=e(implode("\n",$product['includes']??[]))?></textarea></label><label class="wide">Bonus (satu item per baris)<textarea name="bonuses" rows="4" maxlength="6000"><?=e(implode("\n",$product['bonuses']??[]))?></textarea></label><label class="wide">Foto produk<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, WebP · maksimal 2 MB. Foto tersimpan di database dan tetap tersedia setelah deploy.</small></label><?php if(!empty($product['image'])): ?><div class="wide"><img class="admin-photo" src="<?=e($product['image'])?>" alt="Foto produk saat ini"><label class="admin-check"><input type="checkbox" name="remove_photo" value="1">Hapus foto saat ini</label></div><?php endif ?><label class="admin-check wide"><input type="checkbox" name="published" value="1" <?=($product['published']??true)?'checked':''?>>Tayangkan di katalog client</label></div><button class="button" style="margin-top:25px">Simpan produk</button><?php if(!$new&&($product['published']??true)): ?><a class="button secondary" href="product.php?id=<?=e($id)?>">Lihat produk ↗</a><?php endif ?></form></section><aside class="admin-panel"><h2>Produk Anda</h2><p>Klik produk untuk mengubah isi, foto, harga, atau status tayang.</p><?php foreach($products as $key=>$p): ?><a class="product-admin-item" href="admin-products.php?id=<?=e($key)?>"><strong><?=e($p['name'])?></strong><span><?=($p['published']??true)?'Tayang':'Draf'?> · <?=$p['price']===null?'Penawaran':rupiah($p['price'])?></span></a><?php endforeach ?></aside></div></main></body></html>
